 92	describe('listing conversations over the WebSocket protocol', () => {
 93	  it('answers list_sessions for the authenticated user with ISO dates, forwarding limit and before while ignoring any client userId', async () => {
 94	    const inner = new InMemorySessionStore();
 95	    const seen: Array<{userId: string | number; options?: SessionListOptions}> = [];
 96	    const summaries: SessionSummary[] = [
 97	      {
 98	        sessionId: 's2',
 99	        createdAt: new Date('2026-01-01T00:00:00.000Z'),
100	        updatedAt: new Date('2026-01-01T00:02:00.000Z'),
101	        entryCount: 4,
102	      },
103	    ];
104	    const store: SessionStore = {
105	      ...delegatingTo(inner),
106	      listFor: (userId, options) => {
107	        seen.push({userId, options});
108	        return summaries;
109	      },
110	    };
111	    const url = await startEngine(store, 'u1');
112	    const before: SessionCursor = {updatedAt: '2026-01-01T00:05:00.000Z', sessionId: 's3'};
113	
114	    const {frames} = await askAfterConnect(url, {type: 'list_sessions', limit: 10, before, userId: 'u2'});
115	
116	    expect({seen, frames}).toEqual({
117	      seen: [{userId: 'u1', options: {limit: 10, before}}],
118	      frames: [
119	        {
120	          type: 'session_list',
121	          sessions: [
122	            {
123	              sessionId: 's2',
124	              createdAt: '2026-01-01T00:00:00.000Z',
125	              updatedAt: '2026-01-01T00:02:00.000Z',
126	              entryCount: 4,
127	            },
128	          ],
129	        },
130	      ],
131	    });
132	  });
133	
134	  it('answers an empty session_list when the store has no listFor, and SERVER_ERROR with a ws error log when listFor throws', async () => {
135	    const inner = new InMemorySessionStore();
136	    const withoutList = await startEngine(delegatingTo(inner));
137	    const failingList = await startEngine({
138	      ...delegatingTo(inner),
139	      listFor: () => Promise.reject(new Error('database offline')),
140	    });
141	
142	    const unimplemented = await askAfterConnect(withoutList, {type: 'list_sessions'});
143	    const failed = await askAfterConnect(failingList, {type: 'list_sessions'});
144	
145	    expect({
146	      unimplemented: unimplemented.frames,
147	      failed: failed.frames.map(frame => ({type: frame.type, code: frame.code})),
148	      logged: logLines.filter(line => line.level === 'error' && line.category === 'ws'),
149	    }).toEqual({
150	      unimplemented: [{type: 'session_list', sessions: []}],
151	      failed: [{type: 'error', code: 'SERVER_ERROR'}],
152	      logged: [
153	        {
154	          level: 'error',
155	          category: 'ws',
156	          message: expect.any(String),
157	          fields: expect.objectContaining({userId: 'u1', error: 'database offline'}),
158	        },
159	      ],
160	    });
161	  });
162	
163	  it('accepts a bare list_sessions frame and rejects a malformed limit or before with INVALID_MESSAGE without calling listFor', async () => {
164	    const inner = new InMemorySessionStore();
165	    let calls = 0;
166	    const store: SessionStore = {
167	      ...delegatingTo(inner),
168	      listFor: () => {
169	        calls += 1;
170	        return [];
171	      },
172	    };
173	    const url = await startEngine(store);
174	    const badFrames = [
175	      {type: 'list_sessions', limit: 'ten'},
176	      {type: 'list_sessions', limit: -1},
177	      {type: 'list_sessions', limit: 1.5},
178	      {type: 'list_sessions', before: 'not-an-object'},
179	      {type: 'list_sessions', before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: ''}},
180	      {type: 'list_sessions', before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: 'a'.repeat(129)}},
181	      {type: 'list_sessions', before: {updatedAt: 'not-a-date', sessionId: 's1'}},
182	      {type: 'list_sessions', before: {updatedAt: true, sessionId: 's1'}},
183	    ];
184	
185	    const codes: Array<string | undefined> = [];
186	    for (const bad of badFrames) {
187	      const {frames} = await askAfterConnect(url, bad);
188	      codes.push(frames[0]?.code);
189	    }
190	    const {frames: accepted} = await askAfterConnect(url, {type: 'list_sessions'});
191	
192	    expect({codes, accepted, calls}).toEqual({
193	      codes: Array(badFrames.length).fill('INVALID_MESSAGE'),
194	      accepted: [{type: 'session_list', sessions: []}],
195	      calls: 1,
196	    });
197	  });
198	});
