  1	import type {IncomingMessage, ListSessionsMessage} from '../../types/messages.js';
  2	import type {SessionCursor} from '../../types/sessionStore.js';
  3	
  4	const MAX_CONTENT_LENGTH = 10000;
  5	
  6	interface ValidationSuccess {
  7	  valid: true;
  8	  data: IncomingMessage;
  9	}
 10	
 11	interface ValidationFailure {
 12	  valid: false;
 13	  error: string;
 14	}
 15	
 16	export type ValidationResult = ValidationSuccess | ValidationFailure;
 17	
 18	export function validateMessage(payload: unknown): ValidationResult {
 19	  if (typeof payload !== 'object' || payload === null) {
 20	    return {valid: false, error: 'Message must be an object'};
 21	  }
 22	
 23	  const message = payload as Record<string, unknown>;
 24	
 25	  if (typeof message.type !== 'string') {
 26	    return {valid: false, error: 'Message must have a type field'};
 27	  }
 28	
 29	  switch (message.type) {
 30	    case 'user_message':
 31	      return validateUserMessage(message);
 32	    case 'ping':
 33	      return validatePingMessage(message);
 34	    case 'list_sessions':
 35	      return validateListSessionsMessage(message);
 36	    default:
 37	      return {valid: false, error: `Unknown message type: ${message.type}`};
 38	  }
 39	}
 40	
 41	function validateUserMessage(message: Record<string, unknown>): ValidationResult {
 42	  if (typeof message.content !== 'string') {
 43	    return {valid: false, error: 'user_message must have content string'};
 44	  }
 45	
 46	  const trimmed = message.content.trim();
 47	
 48	  if (trimmed.length === 0) {
 49	    return {valid: false, error: 'Message content cannot be empty'};
 50	  }
 51	
 52	  if (message.content.length > MAX_CONTENT_LENGTH) {
 53	    return {valid: false, error: `Message content too long (max ${MAX_CONTENT_LENGTH} chars)`};
 54	  }
 55	
 56	  return {
 57	    valid: true,
 58	    data: {
 59	      type: 'user_message',
 60	      content: message.content,
 61	    },
 62	  };
 63	}
 64	
 65	function validatePingMessage(message: Record<string, unknown>): ValidationResult {
 66	  if (typeof message.timestamp !== 'number') {
 67	    return {valid: false, error: 'ping must have timestamp number'};
 68	  }
 69	
 70	  return {
 71	    valid: true,
 72	    data: {
 73	      type: 'ping',
 74	      timestamp: message.timestamp,
 75	    },
 76	  };
 77	}
 78	
 79	const MAX_SESSION_ID_LENGTH = 128;
 80	
 81	function validateListSessionsMessage(message: Record<string, unknown>): ValidationResult {
 82	  const {limit, before} = message;
 83	  if (limit !== undefined && !(typeof limit === 'number' && Number.isInteger(limit) && limit >= 0)) {
 84	    return {valid: false, error: 'list_sessions limit must be a non-negative integer'};
 85	  }
 86	  const data: ListSessionsMessage = {type: 'list_sessions', ...(limit === undefined ? {} : {limit})};
 87	  if (before === undefined) return {valid: true, data};
 88	
 89	  const cursor = validateCursor(before);
 90	  if (typeof cursor === 'string') return {valid: false, error: cursor};
 91	  return {valid: true, data: {...data, before: cursor}};
 92	}
 93	
 94	// The cursor a client sends back: the last row it saw, after JSON, so a string or an epoch number.
 95	function validateCursor(before: unknown): SessionCursor | string {
 96	  if (typeof before !== 'object' || before === null) return 'list_sessions before must be an object';
 97	  const {sessionId, updatedAt} = before as Record<string, unknown>;
 98	  if (typeof sessionId !== 'string' || sessionId.length === 0 || sessionId.length > MAX_SESSION_ID_LENGTH) {
 99	    return `list_sessions before.sessionId must be a string of 1-${MAX_SESSION_ID_LENGTH} characters`;
100	  }
101	  if (!isTimestamp(updatedAt)) return 'list_sessions before.updatedAt must be a valid timestamp';
102	  return {updatedAt, sessionId};
103	}
104	
105	function isTimestamp(value: unknown): value is string | number {
106	  if (typeof value === 'number') return Number.isFinite(value);
107	  return typeof value === 'string' && Number.isFinite(Date.parse(value));
108	}

